{
  "slug": "check-sync-after-tally-voucher-edit",
  "title": "Verifying an Edited Voucher After the Next Sync",
  "description": "Use the time of an edit and the latest successful sync to decide when a change should appear on Android or web.",
  "category": "Vouchers and Day Book",
  "sections": [
    {
      "heading": "Keep the voucher identifier and edit time",
      "body": "When someone changes an amount in TallyPrime, note the time of the edit and the company, voucher type, number and date. In an illustrative case, the same sales voucher changes from 2,400 to 2,650 after a line correction. The voucher identity stays the same."
    },
    {
      "heading": "Wait for a run that followed the edit",
      "body": "Compare the edit time with the last successful connector run. If the run finished before the edit, use the next successful sync as your checkpoint. Select the same company and date range when you return to the web or phone."
    },
    {
      "heading": "Capture the before and after if needed",
      "body": "If the older amount is still visible, note the amount currently in TallyPrime and the amount displayed in Syncora. Include the connector version and completed run time in the support request so the team can trace exactly which edit you are checking."
    }
  ],
  "relatedPaths": [
    "/guides/tally-sync-troubleshooting",
    "/product-overview"
  ]
}
